const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.0/prime_contracts/%7Bprime_contract_id%7D/payment_application_markup_line_items/%7Bid%7D',
  headers: {'content-type': 'application/json'},
  body: {
    project_id: 55001,
    payment_application_markup_line_item: {
      work_completed_this_period: '1000.00',
      work_completed_retainage_retained_this_period: '100.00',
      work_completed_retainage_released_this_period: '0.00'
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/prime_contracts/%7Bprime_contract_id%7D/payment_application_markup_line_items/%7Bid%7D"),
    Content = new StringContent("{\"project_id\":55001,\"payment_application_markup_line_item\":{\"work_completed_this_period\":\"1000.00\",\"work_completed_retainage_retained_this_period\":\"100.00\",\"work_completed_retainage_released_this_period\":\"0.00\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
